-- Steam linking, Apex stats, game nights with voting, free games of the week. Run in the D1 console before pushing.
CREATE TABLE IF NOT EXISTS steam_links ( user_id INTEGER PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, steam_id TEXT NOT NULL UNIQUE, persona TEXT, avatar TEXT, public INTEGER NOT NULL DEFAULT 1, game_count INTEGER NOT NULL DEFAULT 0, linked_at INTEGER NOT NULL, updated_at INTEGER NOT NULL DEFAULT 0 );
CREATE TABLE IF NOT EXISTS steam_games ( user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, appid INTEGER NOT NULL, playtime INTEGER NOT NULL DEFAULT 0, playtime_2w INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (user_id, appid) );
CREATE INDEX IF NOT EXISTS idx_steam_games_app ON steam_games (appid);
CREATE TABLE IF NOT EXISTS steam_apps ( appid INTEGER PRIMARY KEY, name TEXT, multiplayer INTEGER, fetched_at INTEGER NOT NULL DEFAULT 0 );
CREATE TABLE IF NOT EXISTS apex_links ( user_id INTEGER PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, platform TEXT NOT NULL, name TEXT NOT NULL, data TEXT, week_start INTEGER, week_score INTEGER, week_kills INTEGER, error TEXT, linked_at INTEGER NOT NULL, updated_at INTEGER NOT NULL DEFAULT 0 );
CREATE TABLE IF NOT EXISTS game_nights ( id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, title TEXT NOT NULL, note TEXT, status TEXT NOT NULL DEFAULT 'voting', vote_until INTEGER NOT NULL, game TEXT, starts_at INTEGER, discord_msg_id TEXT, reminded INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL );
CREATE TABLE IF NOT EXISTS game_night_options ( id INTEGER PRIMARY KEY AUTOINCREMENT, night_id INTEGER NOT NULL REFERENCES game_nights(id) ON DELETE CASCADE, kind TEXT NOT NULL, label TEXT NOT NULL, value INTEGER );
CREATE TABLE IF NOT EXISTS game_night_votes ( option_id INTEGER NOT NULL REFERENCES game_night_options(id) ON DELETE CASCADE, night_id INTEGER NOT NULL, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, PRIMARY KEY (option_id, user_id) );
CREATE TABLE IF NOT EXISTS game_night_rsvp ( night_id INTEGER NOT NULL REFERENCES game_nights(id) ON DELETE CASCADE, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, status TEXT NOT NULL, attended INTEGER NOT NULL DEFAULT 0, coins INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (night_id, user_id) );
CREATE TABLE IF NOT EXISTS kv_cache ( key TEXT PRIMARY KEY, value TEXT NOT NULL, updated_at INTEGER NOT NULL );
